const TRIGGER = 'onTicketTransitioned';

// The clear branch keys off correlationid, the only ticket handle a
// `bloodbank.agent.invocation.*` event carries -- it has no board or ticket key.
const store = $getWorkflowStaticData('global');
if (!store.ack) store.ack = {};
const cutoff = Date.now() - 24 * 60 * 60 * 1000;
for (const [k, v] of Object.entries(store.ack)) {
  if (!v || !v.at || v.at < cutoff) delete store.ack[k];
}

const trig = $(TRIGGER).all();
const out = [];
$input.all().forEach((item, i) => {
  const j = item.json || {};
  if (j.invoked !== true) return;            // skipped or ineligible: nothing to show
  const cfg = ACK[j.boardId];
  if (!cfg) return;
  const data = ((trig[i] || trig[0] || {}).json || {}).data || {};
  const ticketId = data.ticket_id || data.task_id;
  if (!ticketId) return;
  if (j.correlationid) {
    store.ack[j.correlationid] = {
      ws: cfg.ws, board: j.boardId, ticketId, labelId: cfg.label,
      ticketKey: j.ticketKey || null, at: Date.now(),
    };
  }
  out.push({ json: { ws: cfg.ws, board: j.boardId, ticketId,
                     labelId: cfg.label, ticketKey: j.ticketKey || null } });
});
return out;

// Clear only what this workflow stamped. Both lanes see every agent's turn-end
// event, so the static-data hit is what says "this one was mine".
const store = $getWorkflowStaticData('global');
const ack = store.ack || {};
const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const cid = j.correlationid || (j.data || {}).correlationid;
  const hit = cid ? ack[cid] : null;
  if (!hit) continue;
  delete ack[cid];
  out.push({ json: hit });
}
store.ack = ack;
return out;
